// ================================================================
// Code â€” Clean Social JSON (v3.0 Simplified)
// 
// Parses AI agent output and formats for Airtable upsert.
// Uses standardized snake_case keys.
// ================================================================

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// HELPERS
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function extractJson(raw) {
  // Remove markdown fences
  raw = raw.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

  // Find JSON boundaries
  const first = raw.indexOf('{');
  const last = raw.lastIndexOf('}');

  if (first === -1 || last === -1 || last <= first) {
    return null;
  }

  return raw.substring(first, last + 1);
}

function formatCarousel(data) {
  if (!data) return 'No carousel content generated';

  // Handle array format
  if (Array.isArray(data)) {
    return data.map((slide, i) => {
      const text = slide.slide_text || slide.text || slide.content || '';
      const visual = slide.visual_description || slide.visual || '';
      let result = `**Slide ${i + 1}**\n${text}`;
      if (visual) result += `\n*(Visual: ${visual})*`;
      return result;
    }).join('\n\n---\n\n');
  }

  // Handle object format { slide_1: {...}, slide_2: {...} }
  if (typeof data === 'object') {
    const keys = Object.keys(data).sort((a, b) => {
      const na = parseInt((a.match(/\d+/) || [0])[0], 10);
      const nb = parseInt((b.match(/\d+/) || [0])[0], 10);
      return na - nb;
    });

    return keys.map((k, idx) => {
      const slide = data[k] || {};
      const text = slide.slide_text || slide.text || slide.content || '';
      const visual = slide.visual_description || slide.visual || '';
      let result = `**Slide ${idx + 1}**\n${text}`;
      if (visual) result += `\n*(Visual: ${visual})*`;
      return result;
    }).join('\n\n---\n\n');
  }

  return typeof data === 'string' ? data : JSON.stringify(data, null, 2);
}

function formatThread(data) {
  if (!data) return 'No thread content generated';

  if (Array.isArray(data)) {
    return data.map((tweet, i) => {
      let text = tweet;
      if (typeof tweet === 'object') {
        text = tweet.tweet_text || tweet.text || tweet.content || JSON.stringify(tweet);
      }
      return `**Tweet ${i + 1}**\n${text}`;
    }).join('\n\n---\n\n');
  }

  return typeof data === 'string' ? data : JSON.stringify(data, null, 2);
}

function formatPinterest(data) {
  if (!data) return 'No Pinterest content generated';

  if (typeof data === 'string') return data;

  const title = data.title || 'Title needed';
  const overlay = data.text_overlay || data.text_overlay_idea || 'Overlay needed';
  const desc = data.description || 'Description needed';

  return `TITLE: ${title}\n\nOVERLAY: ${overlay}\n\nDESCRIPTION: ${desc}`;
}

function formatFacebook(data) {
  if (!data) return 'No Facebook post generated';

  if (typeof data === 'string') return data;

  return data.post_text || data.content || JSON.stringify(data, null, 2);
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// MAIN LOGIC
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const agentOutput = $input.first().json;
const loopItem = $('Loop â€” Social Item Processor').item.json;

// Extract raw text from agent output
let raw = agentOutput.text || agentOutput.output || agentOutput.response || '';
if (!raw && agentOutput.message?.content) raw = agentOutput.message.content;
if (!raw) raw = JSON.stringify(agentOutput);

// Parse JSON
const jsonString = extractJson(raw);
if (!jsonString) {
  return [{
    json: {
      _error: 'No JSON found in agent response',
      _raw: raw.substring(0, 500),
      copy_id: loopItem.copy_id,
      traffic_leak_record_id: loopItem.traffic_leak_record_id
    }
  }];
}

let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch (e) {
  return [{
    json: {
      _error: `JSON parse failed: ${e.message}`,
      _raw: jsonString.substring(0, 500),
      copy_id: loopItem.copy_id,
      traffic_leak_record_id: loopItem.traffic_leak_record_id
    }
  }];
}

// Format content
const igCarouselContent = formatCarousel(parsed.ig_carousel);
const igCaption = parsed.ig_carousel_caption || 'Caption needed';
const igCarousel = `${igCarouselContent}\n\n---CAPTION---\n\n${igCaption}`;

const pinterestPin = formatPinterest(parsed.pinterest_pin);
const xThread = formatThread(parsed.x_thread);
const fbPost = formatFacebook(parsed.fb_post);

// Return standardized snake_case output
return [{
  json: {
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // IDs (passed through from loop for Airtable operations)
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    copy_id: loopItem.copy_id,
    copy_record_id: loopItem.copy_record_id,
    traffic_leak_record_id: loopItem.traffic_leak_record_id,

    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // GENERATED SOCIAL CONTENT (snake_case keys)
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    ig_carousel: igCarousel,
    pinterest_pin: pinterestPin,
    x_twitter_thread: xThread,
    facebook_post: fbPost,

    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    // STAGE TRACKING
    // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    _stage: 'SOCIAL_COMPLETE'
  }
}];

// ================================================================
// Code â€” Normalize Copy Data
// 
// Transforms Copy table Airtable response to snake_case contract.
// Extracts Traffic Leak record ID for status update at end.
// ================================================================

const items = $input.all();
const output = [];

for (const item of items) {
  // Airtable returns { id, createdTime, fields: {...} }
  const fields = item.json.fields || item.json;
  const copyRecordId = item.json.id || '';

  // Get Blog Post - skip if too short
  const blogPost = fields['Blog Post'] || '';
  if (blogPost.length < 200) {
    continue;
  }

  // Extract Traffic Leak record ID from linked field (it's an array)
  const trafficLeakLinks = fields['Traffic Leak'] || [];
  const trafficLeakRecordId = Array.isArray(trafficLeakLinks) 
    ? trafficLeakLinks[0] 
    : (typeof trafficLeakLinks === 'string' ? trafficLeakLinks : '');

  output.push({
    json: {
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      // RECORD IDs (for Airtable operations)
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      copy_record_id: copyRecordId,
      traffic_leak_record_id: trafficLeakRecordId,

      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      // PRIMARY KEY
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      copy_id: fields['Copy ID'] || '',

      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      // COPY CONTENT (source for social generation)
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      blog_post: blogPost,
      video_script: fields['Video Script'] || '',
      voiceover_text: fields['Voice Over Text'] || '',
      research_source: fields['Research Source'] || '',

      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      // EXISTING SOCIAL CONTENT (should be empty for fetched items)
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      ig_carousel: fields['IG Carousel'] || '',
      pinterest_pin: fields['Pinterest Pin'] || '',
      x_twitter_thread: fields['X/Twitter Thread'] || '',
      facebook_post: fields['Facebook Post'] || '',

      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      // STAGE TRACKING
      // â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
      _stage: 'SOCIAL_IN_PROGRESS',
      _source: 'AAS3_NORMALIZED'
    }
  });
}

// Handle empty output
if (output.length === 0) {
  return [{
    json: {
      _empty: true,
      _reason: 'No Copy records need social content',
      _hint: 'Records must have Blog Post (200+ chars) and empty IG Carousel'
    }
  }];
}

return output;
